module TopModule (
    input  wire [7:0] a,
    input  wire [7:0] b,
    output wire [7:0] s,
    output wire       overflow
);

    wire [7:0] sum;
    wire       overflow_flag;

    assign sum = a + b;

    // Compute overflow for signed addition
    assign overflow_flag = (a[7] & b[7] & (~sum[7])) | 
                          (~a[7] & ~b[7] & sum[7]);

    assign s = sum;
    assign overflow = overflow_flag;

endmodule

// Truth Table for TopModule:
// Inputs: a[7:0], b[7:0] (8-bit 2's complement)
// Outputs: s[7:0] (8-bit sum), overflow (1 if signed overflow occurs, 0 otherwise)

// Overflow occurs when:
// - Both a and b are positive, and their sum exceeds 7FH (i.e., the result is negative)
// - Both a and b are negative, and their sum is less than 80H (i.e., the result is positive)
// - Overflow is detected by checking if the sign bits of a and b are the same and the sign bit of the result is different

module TopModule (
    input  [7:0] a,
    input  [7:0] b,
    output [7:0] s,
    output      overflow
);

    wire [8:0] sum;
    assign sum = a + b;
    assign s = sum[7:0];
    assign overflow = (a[7] & b[7] & ~sum[7]) | (~a[7] & ~b[7] & sum[7]);

endmodule

