    input  [2:0] b,
    output [2:0] out_or_bitwise,
    output      out_or_logical,
    output [5:0] out_not
);

    // Bitwise OR of a and b
    assign out_or_bitwise = a | b;

    // Logical OR of a and b (treats vectors as single logic value)
    assign out_or_logical = (a != 3'b000) || (b != 3'b000);

    // Invert a and b, place inverse of b in upper half, inverse of a in lower half
    assign out_not = { ~b, ~a };

