    // 7: 0111 -> a=0, b=1, c=1, d=1
    // 15: 1111 -> a=1, b=1, c=1, d=1
    // SOP expression: (a' b' c d') + (a' b c d) + (a b c d)
    assign out_sop = (!a & !b & c & !d) | (!a & b & c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for inputs corresponding to 0, 1, 4, 5, 6, 9, 10, 13, 14
    // We need to find the minimal POS expression that covers all these cases
    // out_pos is 1 for inputs corresponding to 2, 7, 15
    // So, the POS expression should be the product of sums that are 0 for these inputs

    // The minimal POS expression is:
    // (a + b + c' + d') * (a + b' + c + d') * (a + b' + c' + d) * (a' + b + c + d)
    assign out_pos = 
        (a | b | !c | !d) &
        (a | !b | c | !d) &
        (a | !b | !c | d) &
        (!a | b | c | d);

endmodule

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // State transition logic
    // next_state = (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) :
    //              (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) :
    //              (state == 4'b0100) ? (in ? 4'b0001 : 4'b1000) :
    //              (state == 4'b1000) ? (in ? 4'b0100 : 4'b0010) : 4'b0000;

    // Output logic
    // out = (state == 4'b1000) ? 1 : 0;

    // Implementing the logic using case statements for clarity
    always @(*) begin
        case (state)
            4'b0001: next_state = (in) ? 4'b0010 : 4'b0001;
            4'b0010: next_state = (in) ? 4'b0010 : 4'b0100;
            4'b0100: next_state = (in) ? 4'b0001 : 4'b1000;
            4'b1000: next_state = (in) ? 4'b0100 : 4'b0010;
            default: next_state = 4'b0000;
        endcase

        case (state)
            4'b1000: out = 1;
            default: out = 0;
        endcase
    end

endmodule

// State Transition Table for TopModule
// State | Next state in=0, Next state in=1 | Output
// A     | A, B                             | 0
// B     | C, B                             | 0
// C     | A, D                             | 0
// D     | C, B                             | 1

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000
    // Derive next_state and out based on state and in

    // Output logic: out is 1 only when state is D
    assign out = (state == 4'b1000) ? 1 : 0;

    // Next state logic
    // For each state, determine next_state based on in
    // in=0: next_state is the first value, in=1: next_state is the second value

    // A (0001) -> in=0: A (0001), in=1: B (0010)
    // B (0010) -> in=0: C (0100), in=1: B (0010)
    // C (0100) -> in=0: A (0001), in=1: D (1000)
    // D (1000) -> in=0: C (0100), in=1: B (0010)

    // Combine logic for next_state
    assign next_state = 
        (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) :
        (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) :
        (state == 4'b0100) ? (in ? 4'b1000 : 4'b0001) :
        (state == 4'b1000) ? (in ? 4'b0010 : 4'b0100) : 4'b0000;

endmodule

module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output      out
);

    // State transition logic
    // One-hot encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Determine next state based on current state and input
    // State A (0001)
    assign next_state = (state == 4'b0001) ? 
                        (in ? 4'b0010 : 4'b0001) : // A -> A (in=0), B (in=1)
                      // State B (0010)
                        (state == 4'b0010) ? 
                        (in ? 4'b0010 : 4'b0100) : // B -> B (in=0), C (in=1)
                      // State C (0100)
                        (state == 4'b0100) ? 
                        (in ? 4'b1000 : 4'b0001) : // C -> D (in=0), A (in=1)
                      // State D (1000)
                        (state == 4'b1000) ? 
                        (in ? 4'b0010 : 4'b0100) : // D -> B (in=0), C (in=1)
                      4'b0000; // default case

    // Output logic (Moore machine: output depends only on current state)
    assign out = (state == 4'b1000) ? 1 : 0; // Output is 1 only when in state D

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [9:0] data,
    output reg tc
);

    reg [9:0] counter;

    always @(posedge clk) begin
        if (load) begin
            counter <= data;
            tc <= 1'b0;
        end else begin
            if (counter == 10'd0) begin
                tc <= 1'b1;
            end else begin
                counter <= counter - 1;
                tc <= 1'b0;
            end
        end
    end

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs: clk, load, data[9:0]
// Outputs: tc
//
// State Variables:
// cnt[9:0] - 10-bit down counter
// tc - terminal count signal (1 when cnt == 0)
//
// On each positive edge of clk:
// 1. If load is 1, load cnt with data
// 2. Else, decrement cnt by 1
// 3. If cnt == 0, set tc to 1 (and keep it 1 until next load)
// 4. If cnt != 0, set tc to 0

module TopModule (
    input  clk,
    input  load,
    input  data,
    output reg tc
);

    // Internal 10-bit counter
    reg [9:0] cnt;

    always @(posedge clk) begin
        if (load) begin
            cnt <= data;
            tc <= (cnt == 0) ? 1 : 0;
        end else begin
            if (cnt != 0) begin
                cnt <= cnt - 1;
                tc <= (cnt == 0) ? 1 : 0;
            end
        end
    end

endmodule

