    input  reset,
    input  x,
    output z
);

    reg [2:0] y;
    wire [2:0] next_y;

    // Output logic
    assign z = (y == 3'b011) ? 1 : 0;

    // Next state logic
    always @(*) begin
        case (y)
            3'b000: next_y = (x == 1) ? 3'b001 : 3'b000;
            3'b001: next_y = (x == 1) ? 3'b100 : 3'b001;
            3'b010: next_y = (x == 1) ? 3'b001 : 3'b010;
            3'b011: next_y = (x == 1) ? 3'b010 : 3'b001;
            3'b100: next_y = (x == 1) ? 3'b100 : 3'b011;
            default: next_y = 3'b000;
        endcase
    end

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= next_y;
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  in,
    output out
);

typedef enum logic [1:0] {A, B, C, D} state_t;

state_t current_state, next_state;

always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
        current_state <= A;
    end else begin
        current_state <= next_state;
    end
end

always_comb begin
    next_state = current_state;
    out = 1'b0;

    case (current_state)
        A: begin
            next_state = (in == 1'b0) ? A : B;
            out = 1'b0;
        end
        B: begin
            next_state = (in == 1'b0) ? C : B;
            out = 1'b0;
        end
        C: begin
            next_state = (in == 1'b0) ? A : D;
            out = 1'b0;
        end
        D: begin
            next_state = (in == 1'b0) ? C : B;
            out = 1'b1;
        end
        default: begin
            next_state = A;
            out = 1'b0;
        end
    endcase
end

endmodule

module TopModule (
