    output out
);

    // Karnaugh map implementation
    // out = (a & b & c) | (a & c) | (b & c) | (a & b) | (a & d) | (b & d) | (c & d)

    assign out = (a & b & c) | (a & c) | (b & c) | (a & b) | (a & d) | (b & d) | (c & d);

endmodule

