module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

typedef enum logic [1:0] {A, B, C, D, E} state_t;

state_t current_state, next_state;
logic [2:0] count;
logic z_out;

always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
        count <= 3'b000;
        z_out <= 1'b0;
    end else begin
        current_state <= next_state;
        if (current_state == A) begin
            if (s) begin
                next_state <= B;
                count <= 3'b000;
            end else begin
                next_state <= A;
            end
        end else if (current_state == B) begin
            if (count < 3) begin
                next_state <= B;
                count <= count + 1;
            end else begin
                next_state <= C;
                count <= 3'b000;
            end
        end else if (current_state == C) begin
            if (count < 3) begin
                next_state <= C;
                count <= count + 1;
            end else begin
                next_state <= D;
                count <= 3'b000;
            end
        end else if (current_state == D) begin
            if (count < 3) begin
                next_state <= D;
                count <= count + 1;
            end else begin
                next_state <= E;
                count <= 3'b000;
            end
        end else if (current_state == E) begin
            next_state <= A;
        end
    end
end

always_comb begin
    next_state = current_state;
    z = 1'b0;

    if (current_state == B) begin
        if (count < 3) begin
            next_state = B;
        end else begin
            next_state = C;
        end
    end else if (current_state == C) begin
        if (count < 3) begin
            next_state = C;
        end else begin
            next_state = D;
        end
    end else if (current_state == D) begin
        if (count < 3) begin
            next_state = D;
        end else begin
            next_state = E;
        end
    end else if (current_state == E) begin
        next_state = A;
    end

    if (current_state == D && count == 3) begin
        if (w == 1) begin
            z = 1'b1;
        end
    end
end

endmodule

// State Transition Table for TopModule
// States: A, B, C, D, E
// Inputs: s, w
// Outputs: z

// State | s | w | Next State | z
// A     | 0 | 0 | A          | 0
// A     | 0 | 1 | A          | 0
// A     | 1 | 0 | B          | 0
// A     | 1 | 1 | B          | 0
// B     | 0 | 0 | B          | 0
// B     | 0 | 1 | B          | 0
// B     | 1 | 0 | C          | 0
// B     | 1 | 1 | D          | 0
// C     | 0 | 0 | C          | 0
// C     | 0 | 1 | C          | 0
// C     | 1 | 0 | E          | 0
// C     | 1 | 1 | D          | 0
// D     | 0 | 0 | D          | 0
// D     | 0 | 1 | D          | 0
// D     | 1 | 0 | E          | 0
// D     | 1 | 1 | E          | 1
// E     | 0 | 0 | B          | 0
// E     | 0 | 1 | B          | 0
// E     | 1 | 0 | B          | 0
// E     | 1 | 1 | B          | 0

module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

    // Define states
    typedef enum reg [2:0] {
        A = 3'b000,
        B = 3'b001,
        C = 3'b010,
        D = 3'b011,
        E = 3'b100
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state and output logic
    always @(*) begin
        next_state = current_state;
        z = 1'b0;

        case (current_state)
            A: begin
                if (s) begin
                    next_state = B;
                    z = 1'b0;
                end else begin
                    next_state = A;
                    z = 1'b0;
                end
            end

            B: begin
                next_state = B;
                z = 1'b0;
            end

            C: begin
                if (w) begin
                    next_state = D;
                end else begin
                    next_state = C;
                end
                z = 1'b0;
            end

            D: begin
                if (w) begin
                    next_state = E;
                end else begin
                    next_state = D;
                end
                z = 1'b0;
            end

            E: begin
                if (w) begin
                    next_state = B;
                end else begin
                    next_state = B;
                end
                z = 1'b1;
            end

            default: begin
                next_state = A;
                z = 1'b0;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

typedef enum reg [1:0] {A, B, C, D, E} state_t;

state_t current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
    end else begin
        current_state <= next_state;
    end
end

// State transition logic
always @(*) begin
    next_state = current_state;
    case (current_state)
        A: begin
            if (s) begin
                next_state = B;
            end else begin
                next_state = A;
            end
        end
        B: begin
            next_state = C;
        end
        C: begin
            next_state = D;
        end
        D: begin
            next_state = E;
        end
        E: begin
            next_state = B;
        end
        default: next_state = A;
    endcase
end

// Output logic
always @(*) begin
    case (current_state)
        A: z = 1'b0;
        B: z = 1'b0;
        C: z = 1'b0;
        D: z = 1'b0;
        E: z = 1'b0;
        default: z = 1'b0;
    endcase
end

// Count the number of 1s in w over the last three clock cycles
reg [2:0] w_count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        w_count <= 3'b000;
    end else begin
        if (current_state == B) begin
            w_count <= {w_count[1:0], w};
        end
    end
end

// Set z to 1 if exactly two of the last three w's are 1
always @(*) begin
    if (current_state == E) begin
        if (w_count == 3'b110 || w_count == 3'b101 || w_count == 3'b011) begin
            z = 1'b1;
        end else begin
            z = 1'b0;
        end
    end else begin
        z = 1'b0;
    end
end

endmodule

module TopModule (
    input  [2:0] y,
    input        w,
    output       Y1
);

    // State codes:
    // A = 000, B = 001, C = 010, D = 011, E = 100, F = 101

    // Next-state logic for y[1]
    // y[1] is the second bit of the state code

    // Current state
    reg [2:0] current_state;

    // Assign current_state from input y
    always @(y) begin
        current_state = y;
    end

    // Next state logic
    reg [2:0] next_state;

    always @(current_state, w) begin
        case (current_state)
            3'b000: // A
                if (w) next_state = 3'b000;
                else next_state = 3'b001;
            3'b001: // B
                if (w) next_state = 3'b010;
                else next_state = 3'b011;
            3'b010: // C
                if (w) next_state = 3'b100;
                else next_state = 3'b011;
            3'b011: // D
                if (w) next_state = 3'b000;
                else next_state = 3'b101;
            3'b100: // E
                if (w) next_state = 3'b100;
                else next_state = 3'b101;
            3'b101: // F
                if (w) next_state = 3'b010;
                else next_state = 3'b101;
            default: next_state = 3'b000;
        endcase
    end

    // Output Y1 is y[1]
    assign Y1 = y[1];

endmodule

