            3'b000_1: next_y1 = 1'b0; // A, w=1 -> A (y[1] remains 0)
            3'b001_0: next_y1 = 1'b1; // B, w=0 -> C (y[1] becomes 1)
            3'b001_1: next_y1 = 1'b1; // B, w=1 -> D (y[1] becomes 1)
