module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

typedef enum logic [1:0] {A=2'b00, B=2'b01, C=2'b10, D=2'b11} state_t;

state_t current_state, next_state;
logic [2:0] count;
logic z_out;

always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
        count <= 3'b000;
        z_out <= 1'b0;
    end else begin
        current_state <= next_state;
        if (current_state == A) begin
            if (s) begin
                next_state <= B;
                count <= 3'b000;
            end else begin
                next_state <= A;
            end
        end else if (current_state == B) begin
            if (count < 3) begin
                next_state <= B;
                count <= count + 1;
            end else begin
                next_state <= C;
                count <= 3'b000;
            end
        end else if (current_state == C) begin
            if (count < 3) begin
                next_state <= C;
                count <= count + 1;
            end else begin
                next_state <= D;
                count <= 3'b000;
            end
        end else if (current_state == D) begin
            if (count < 3) begin
                next_state <= D;
                count <= count + 1;
            end else begin
                next_state <= A;
                count <= 3'b000;
            end
        end
    end
end

always_comb begin
    next_state = current_state;
    z = 1'b0;

    if (current_state == B) begin
        next_state = B;
    end else if (current_state == C) begin
        next_state = C;
    end else if (current_state == D) begin
        next_state = D;
    end else if (current_state == A) begin
        next_state = A;
    end

    if (current_state == D) begin
        if (count == 3) begin
            if (w == 1) begin
                z = 1'b1;
            end
        end
    end
end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output reg z
);

    // Define states
    typedef enum reg [2:0] {
        A = 3'b000,
        B = 3'b001,
        C = 3'b010,
        D = 3'b011,
        E = 3'b100
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state and output logic
    always @(*) begin
        next_state = current_state;
        z = 1'b0;

        case (current_state)
            A: begin
                if (s) begin
                    next_state = B;
                end else begin
                    next_state = A;
                end
            end

            B: begin
                next_state = B;
            end

            C: begin
                if (w) begin
                    next_state = D;
                end else begin
                    next_state = C;
                end
            end

            D: begin
                if (w) begin
                    next_state = E;
                end else begin
                    next_state = D;
                end
            end

            E: begin
                if (w) begin
                    next_state = B;
                end else begin
                    next_state = B;
                end
