        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

typedef enum reg [1:0] {A=2'b00, B=2'b01, C=2'b10, D=2'b11, E=2'b00} state_t;

state_t current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
    end else begin
        current_state <= next_state;
    end
end

// State transition logic
always @(*) begin
    next_state = current_state;
    case (current_state)
        A: begin
            if (s) begin
                next_state = B;
            end else begin
                next_state = A;
            end
        end
        B: begin
            next_state = C;
        end
        C: begin
            next_state = D;
        end
        D: begin
            next_state = E;
        end
        E: begin
            next_state = B;
        end
        default: next_state = A;
    endcase
end

// Output logic
always @(*) begin
    case (current_state)
        A: z = 1'b0;
        B: z = 1'b0;
        C: z = 1'b0;
        D: z = 1'b0;
        E: z = 1'b0;
        default: z = 1'b0;
    endcase
end

// Count the number of 1s in w over the last three clock cycles
reg [2:0] w_count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        w_count <= 3'b000;
    end else begin
        if (current_state == B) begin
            w_count <= {w_count[1:0], w};
        end
    end
end

// Set z to 1 if exactly two of the last three w's are 1
always @(*) begin
    if (current_state == E) begin
        if (w_count == 3'b110 || w_count == 3'b101 || w_count == 3'b011) begin
            z = 1'b1;
        end else begin
            z = 1'b0;
        end
    end else begin
        z = 1'b0;
    end
end

endmodule

