module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00; // Reset to state 0 (below s[0])
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state (for detecting level increase)
            previous_state <= current_state;

            // Output logic based on current state
            case (current_state)
                2'b11: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2'b10: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            // Check if previous level was lower than current level (level increased)
            if (previous_state < current_state) begin
                dfr <= 1'b1;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_dig;
    reg prev_bump_left;
    reg prev_bump_right;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_dig <= 1'b0;
            prev_bump_left <= 1'b0;
            prev_bump_right <= 1'b0;
        end else begin
            prev_ground <= ground;
            prev_dig <= dig;
            prev_bump_left <= bump_left;
            prev_bump_right <= bump_right;

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (!prev_ground && ground) begin
                // Ground reappeared, resume walking
                if (current_state == FALLING) begin
                    next_state = WALK_LEFT;
                    if (walk_left) next_state = WALK_LEFT;
                    else next_state = WALK_RIGHT;
                end
            end else if (!ground) begin
                // Falling
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (dig && current_state == WALK_LEFT && prev_ground) begin
                // Start digging
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig && current_state == WALK_LEFT && prev_ground) begin
                // Continue digging
                next_state = DIGGING;
                digging <= 1'b1;
            end else if (dig && current_state == DIGGING && !ground) begin
                // Digging completed, fall
                next_state = FALLING;
                digging <= 1'b0;
                aaah <= 1'b1;
            end else if (dig && current_state == DIGGING && ground) begin
                // Resume walking
                next_state = WALK_LEFT;
                digging <= 1'b0;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (bump_left || bump_right) begin
                // Change direction if not digging or falling
                if (current_state != FALLING && current_state != DIGGING) begin
                    if (bump_left) begin
                        next_state = WALK_RIGHT;
                        walk_left <= 1'b0;
                        walk_right <= 1'b1;
                    end else if (bump_right) begin
                        next_state = WALK_LEFT;
                        walk_left <= 1'b1;
                        walk_right <= 1'b0;
                    end
                end
            end else if (current_state == WALK_LEFT) begin
                next_state = WALK_LEFT;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (current_state == WALK_RIGHT) begin
                next_state = WALK_RIGHT;
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end
        end
    end

    // Output logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
        end else begin
            walk_left <= next_state == WALK_LEFT;
            walk_right <= next_state == WALK_RIGHT;
            aaah <= (next_state == FALLING) || (current_state == FALLING);
            digging <= (next_state == DIGGING);
        end
    end

endmodule

// State Transition Table for TopModule

// States:
// S0: walk_left
// S1: walk_right
// S2: falling (aaah)
// S3: digging

// Inputs: clk, areset, bump_left, bump_right, ground, dig
// Outputs: walk_left, walk_right, aaah, digging

// State | bump_left | bump_right | ground | dig | Next State | walk_left | walk_right | aaah | digging
// S0    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S0    | 1        | 0         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 0        | 1         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 1        | 1         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S0    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S1    | 0        | 1         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S1    | 1        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S1    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S1    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S2    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S2    | 0        | 0         | 1     | 1  | S2         | 0         | 0          | 1    | 1
// S2    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S2    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S3    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S3    | 0        | 0         | 1     | 1  | S3         | 0         | 0          | 0    | 1
// S3    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S3    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 0

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    typedef enum reg [1:0] {
        S0 = 2'b00, // walk_left
        S1 = 2'b01, // walk_right
        S2 = 2'b10, // falling
        S3 = 2'b11  // digging
    } state_t;

    state_t current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            current_state <= next_state;
            walk_left <= (current_state == S0) ? 1 : (current_state == S1) ? 0 : (current_state == S2 || current_state == S3) ? 0 : walk_left;
            walk_right <= (current_state == S0) ? 0 : (current_state == S1) ? 1 : (current_state == S2 || current_state == S3) ? 0 : walk_right;
            aaah <= (current_state == S2) ? 1 : 0;
            digging <= (current_state == S3) ? 1 : 0;
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            S0: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S1;
                    else if (!ground) next_state = S2;
                end
            end
            S1: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S0;
                    else if (!ground) next_state = S2;
                end
            end
            S2: begin
                if (ground) next_state = S0;
            end
            S3: begin
                if (!ground) next_state = S2;
                else if (dig) next_state = S3;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1 && ground == 0) begin
                next_state = FALLING;
                aaah <= 1;
                digging <= 0;
            end else if (current_state == FALLING && ground == 1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1 - prev_direction;
                aaah <= 0;
                digging <= 0;
            end else if (dig == 1 && current_state == WALK_LEFT && ground == 1) begin
                next_state = DIGGING;
                digging <= 1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig == 1 && current_state == WALK_RIGHT && ground == 1) begin
                next_state = DIGGING;
                digging <= 1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 0) begin
                next_state = FALLING;
                aaah <= 1;
                digging <= 0;
            end else if (current_state == DIGGING && ground == 1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1 - prev_direction;
                aaah <= 0;
                digging <= 0;
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state and outputs
            current_state <= next_state;

            if (current_state == WALK_LEFT) begin
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (current_state == WALK_RIGHT) begin
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end else if (current_state == FALLING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end

            if (current_state == FALLING) begin
                aaah <= 1'b1;
            end else begin
                aaah <= 1'b0;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'd0;
            prev_s <= 3'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Determine current sensor state
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        // Above s[2]
                        state <= 2'd3;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else begin
                        // Between s[2] and s[1]
                        state <= 2'd2;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end else begin
                    // Between s[1] and s[0]
                    state <= 2'd1;
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            end else begin
                // Below s[0]
                state <= 2'd0;
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Check if the previous level was lower than the current level
    always @(posedge clk) begin
        // Determine if the current level is higher than the previous level
        // by checking if any sensor has transitioned from 0 to 1
        // and the corresponding sensor in the previous state was 0
        if (s[2] && !prev_s[2]) begin
            dfr <= 1'b1;
        end else if (s[1] && !prev_s[1]) begin
            dfr <= 1'b1;
        end else if (s[0] && !prev_s[0]) begin
            dfr <= 1'b1;
        end else begin
            dfr <= 1'b0;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = reset, 1-14 = states based on sensor transitions
    reg [3:0] state;

    always @(posedge clk) begin
        if (reset) begin
            state <= 4'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            case (state)
                4'd0: begin // Reset state
                    if (s == 3'b000) begin
                        state <= 4'd0;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b1;
                    end else begin
                        state <= 4'd7;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end
                end

                4'd1: begin // s = 001, previous = 000
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                    state <= 4'd8;
                end

                4'd2: begin // s = 010, previous = 001
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                    state <= 4'd9;
                end

                4'd3: begin // s = 011, previous = 010
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                    state <= 4'd10;
                end

                4'd4: begin // s = 100, previous = 011
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                    state <= 4'd11;
                end

                4'd5: begin // s = 101, previous = 100
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                    state <= 4'd12;
                end

                4'd6: begin // s = 110, previous = 101
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                    state <= 4'd13;
                end

                4'd7: begin // s = 111, previous = 110
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                    state <= 4'd14;
                end

                4'd8: begin // s = 001, previous = 000
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                    state <= 4'd8;
                end

                4'd9: begin // s = 010, previous = 001
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                    state <= 4'd9;
                end

                4'd10: begin // s = 011, previous = 010
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                    state <= 4'd10;
                end

                4'd11: begin // s = 100, previous = 011
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                    state <= 4'd11;
                end

                4'd12: begin // s = 101, previous = 100
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                    state <= 4'd12;
                end

                4'd13: begin // s = 110, previous = 101
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                    state <= 4'd13;
                end

                4'd14: begin // s = 111, previous = 110
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                    state <= 4'd14;
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset to state 0 (below s[0]) with all outputs asserted
            current_state <= 2'b00;
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state (for detecting level increase)
            previous_state <= current_state;

            // Output logic based on current state
            case (current_state)
                2'b11: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2'b10: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            // Check if previous level was lower than current level (level increased)
            if (previous_state < current_state) begin
                dfr <= 1'b1;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_dig;
    reg prev_bump_left;
    reg prev_bump_right;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_dig <= 1'b0;
            prev_bump_left <= 1'b0;
            prev_bump_right <= 1'b0;
        end else begin
            prev_ground <= ground;
            prev_dig <= dig;
            prev_bump_left <= bump_left;
            prev_bump_right <= bump_right;

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (!prev_ground && ground) begin
                // Ground reappeared, resume walking
                if (current_state == FALLING) begin
                    next_state = (walk_left) ? WALK_LEFT : WALK_RIGHT;
                end
            end else if (!ground) begin
                // Falling
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (dig && current_state == WALK_LEFT && prev_ground) begin
                // Start digging
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig && current_state == DIGGING && !ground) begin
                // Digging completed, fall
                next_state = FALLING;
                digging <= 1'b0;
                aaah <= 1'b1;
            end else if (dig && current_state == DIGGING && ground) begin
                // Resume walking
                next_state = WALK_LEFT;
                digging <= 1'b0;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (bump_left || bump_right) begin
                // Change direction if not digging or falling
                if (current_state != FALLING && current_state != DIGGING) begin
                    if (bump_left) begin
                        next_state = WALK_RIGHT;
                        walk_left <= 1'b0;
                        walk_right <= 1'b1;
                    end else if (bump_right) begin
                        next_state = WALK_LEFT;
                        walk_left <= 1'b1;
                        walk_right <= 1'b0;
                    end
                end
            end else if (current_state == WALK_LEFT) begin
                next_state = WALK_LEFT;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (current_state == WALK_RIGHT) begin
                next_state = WALK_RIGHT;
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end
        end
    end

    // Output logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
        end else begin
            walk_left <= (next_state == WALK_LEFT);
            walk_right <= (next_state == WALK_RIGHT);
            aaah <= (next_state == FALLING);
            digging <= (next_state == DIGGING);
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    typedef enum reg [1:0] {
        S0 = 2'b00, // walk_left
        S1 = 2'b01, // walk_right
        S2 = 2'b10, // falling
        S3 = 2'b11  // digging
    } state_t;

    state_t current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            current_state <= next_state;
            walk_left <= (current_state == S0) ? 1 : (current_state == S1) ? 0 : (current_state == S2 || current_state == S3) ? 0 : walk_left;
            walk_right <= (current_state == S0) ? 0 : (current_state == S1) ? 1 : (current_state == S2 || current_state == S3) ? 0 : walk_right;
            aaah <= (current_state == S2) ? 1 : 0;
            digging <= (current_state == S3) ? 1 : 0;
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            S0: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S1;
                    else if (!ground) next_state = S2;
                end
            end
            S1: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S0;
                    else if (!ground) next_state = S2;
                end
            end
            S2: begin
                if (ground) next_state = S0;
            end
            S3: begin
                if (!ground) next_state = S2;
                else if (dig) next_state = S3;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1 && ground == 0) begin
                next_state = FALLING;
                aaah <= 1;
                digging <= 0;
            end else if (current_state == FALLING && ground == 1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1 - prev_direction;
                aaah <= 0;
                digging <= 0;
            end else if (dig == 1 && current_state == WALK_LEFT && ground == 1) begin
                next_state = DIGGING;
                digging <= 1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig == 1 && current_state == WALK_RIGHT && ground == 1) begin
                next_state = DIGGING;
                digging <= 1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 0) begin
                next_state = FALLING;
                aaah <= 1;
                digging <= 0;
            end else if (current_state == DIGGING && ground == 1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1 - prev_direction;
                aaah <= 0;
                digging <= 0;
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state and outputs
            current_state <= next_state;

            // Set direction based on current state
            if (current_state == WALK_LEFT) begin
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (current_state == WALK_RIGHT) begin
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end else begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end

            // Set aaah based on current state
            if (current_state == FALLING) begin
                aaah <= 1'b1;
            end else begin
                aaah <= 1'b0;
            end
        end
    end

endmodule
